mapper.select:
select ITEM_CODE id, ITEM_VALUE "text"
from SYS_DATADICT_LIST
DICT_CODE = #{dictCode}

select * from ( select * from ( select '' workflowId, eew.ENTRUST_ID entrustId, eew.PORTFOLIO_ID portfolioId, eew.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, eew.FINPROD_TYPE2 finprodType2, eew.PS ps, eew.CCY ccy, eew.ENTRUST_DATE entrustDate, eew.ENTRUST_AMT entrustAmt, eew.ENTRUST_STATUS entrustStatus from ETR_ENTRUST_WW eew left join FIN_PRODUCT fp on fp.FINPROD_ID = eew.FINPROD_ID
eew.ENTRUST_ID = #{entrustId}
union all select weew.WORKFLOW_ID workflowId, weew.ENTRUST_ID entrustId, weew.PORTFOLIO_ID portfolioId, weew.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, weew.FINPROD_TYPE2 finprodType2, weew.PS ps, weew.CCY ccy, weew.ENTRUST_DATE entrustDate, weew.ENTRUST_AMT entrustAmt, weew.ENTRUST_STATUS entrustStatus
from WFL_ETR_ENTRUST_WW weew left join FIN_PRODUCT fp on fp.FINPROD_ID = weew.FINPROD_ID
weew.ENTRUST_ID = #{entrustId}
) order by entrustStatus desc ) where rownum=1

SELECT T1.ENTRUST_ID||T1.PORTFOLIO_ID entrustId, T1.PORTFOLIO_ID, T.FINPROD_ID, T1.PORTFOLIO_AMT entrustAmt, T.PS, T2.TYPE_8 assetType FROM ETR_ENTRUST_WW T INNER JOIN ETR_ENTRUST_WW_DETAIL T1 ON T.ENTRUST_ID = T1.ENTRUST_ID INNER JOIN FIN_PRODUCT_TYPE T2 ON T.FINPROD_ID = T2.FINPROD_ID
AND T.ENTRUST_ID IN
#{item,jdbcType=VARCHAR}

select portfolioId,portfolioName,PORTFOLIO_AMT,subjectNum from ( select ppt.PORTFOLIO_ID portfolioId, ppt.PORTFOLIO_NAME portfolioName, eewd.PORTFOLIO_AMT as PORTFOLIO_AMT, ppt.AMOUNT subjectNum
from ETR_ENTRUST_WW_DETAIL eewd inner join ETR_ENTRUST_WW eew on eewd.ENTRUST_ID = eew.ENTRUST_ID
inner join ( select psp.PORTFOLIO_ID, pp.PORTFOLIO_NAME, psp.FINPROD_ID, sum (psp.AMOUNT) AMOUNT
from PTL_SEC_POSITION psp inner join PTL_PORTFOLIO pp on psp.PORTFOLIO_ID = pp.PORTFOLIO_ID where psp.FINPROD_ID = #{portfolioIdChange} and psp.BRANCH = '0' and psp.HODING_TYPE = '03'
and psp.CDATE = to_date(#{entrustDate},'yy/mm/dd')
GROUP by psp.PORTFOLIO_ID,pp.PORTFOLIO_NAME,psp.FINPROD_ID ) ppt on ppt.PORTFOLIO_ID = eewd.PORTFOLIO_ID
where eew.PORTFOLIO_ID = #{portfolioId}
and eewd.ENTRUST_ID = #{entrustId}
) order by subjectNum

select * from ( select '' workflowId, eew.ENTRUST_ID entrustId, eew.PORTFOLIO_ID portfolioId, eew.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, eew.FINPROD_TYPE2 finprodType2, eew.PS ps, eew.CCY ccy, eew.ENTRUST_DATE entrustDate, eew.ENTRUST_AMT entrustAmt, eew.ENTRUST_STATUS entrustStatus from ETR_ENTRUST_WW eew left join FIN_PRODUCT fp on fp.FINPROD_ID = eew.FINPROD_ID
eew.ENTRUST_ID = #{entrustId}
)
